#include <stdlib.h>
typedef struct{struct TreeNode**st;int top,cap;}BSTIterator;static void push(BSTIterator*i,struct TreeNode*n){while(n){if(i->top==i->cap){i->cap*=2;i->st=realloc(i->st,i->cap*sizeof(*i->st));}i->st[i->top++]=n;n=n->left;}}BSTIterator* bSTIteratorCreate(struct TreeNode*r){BSTIterator*i=malloc(sizeof(*i));i->cap=16;i->top=0;i->st=malloc(i->cap*sizeof(*i->st));push(i,r);return i;}int bSTIteratorNext(BSTIterator*i){struct TreeNode*n=i->st[--i->top];push(i,n->right);return n->val;}bool bSTIteratorHasNext(BSTIterator*i){return i->top>0;}void bSTIteratorFree(BSTIterator*i){free(i->st);free(i);}
